await test('Owner moderation retains normal review events; Staff moderation records in common audit', async () => {
  const campOwner = member1; // member1 has role 'member'
  const campId = 'bbbbbbbb-aaaa-aaaa-aaaa-aaaaaaaaaaaa';
  const rep1 = 'bbbbbbbb-1111-aaaa-aaaa-aaaaaaaaaaaa';
  const rep2 = 'bbbbbbbb-2222-aaaa-aaaa-aaaaaaaaaaaa';

  await db.exec(`
    insert into public.campaigns(id, owner_id, app_name, package_name, status)
    values ('${campId}', '${campOwner}', 'Moderation Test', 'com.test.mod', 'open')
    on conflict (id) do nothing;

    insert into public.campaign_members(campaign_id, user_id)
    values ('${campId}', '${member2}')
    on conflict do nothing;

    insert into public.tester_reports(id, campaign_id, user_id, status, content, provisional_granted_credits, created_at)
    values
      ('${rep1}', '${campId}', '${member2}', 'pending', 'Report 1', 2, now()),
      ('${rep2}', '${campId}', '${member2}', 'pending', 'Report 2', 2, now())
    on conflict do nothing;
  `);

  // 1. Owner approves report 1 -> report_review_events written, but ZERO admin_action_events
  const evCountBefore = (await db.query(`select count(*)::int as cnt from public.admin_action_events where action like 'staff_%'`)).rows[0].cnt;
  const ownerApprove = (await asActor(campOwner, `select public.approve_tester_report('${rep1}', 0) as r`)).rows[0].r;
  assert.equal(ownerApprove.success, true);

  const evCountOwner = (await db.query(`select count(*)::int as cnt from public.admin_action_events where action like 'staff_%'`)).rows[0].cnt;
  assert.equal(evCountOwner, evCountBefore, 'Owner moderation must NOT record in admin_action_events');

  // 2. Staff (admin) rejects report 2 -> records in admin_action_events as staff_reject_tester_report
  const staffReject = (await asActor(admin1, `select public.reject_tester_report('${rep2}', 'Staff reject test', 'INVALID_SCREENSHOT') as r`)).rows[0].r;
  assert.equal(staffReject.success, true);

  const evStaff = (await db.query(`select action, target_id, actor_id from public.admin_action_events where action = 'staff_reject_tester_report' and target_id = '${rep2}' order by created_at desc limit 1`)).rows[0];
  assert.ok(evStaff, 'Staff moderation must record in admin_action_events');
  assert.equal(evStaff.actor_id, admin1);
});

